ROLE_PERMISSIONS = {
    "learner": {"read_lesson", "take_quiz", "run_scan"},
    "admin": {"read_lesson", "take_quiz", "run_scan", "edit_course", "view_audit_log"},
}

def allowed(role, action):
    return action in ROLE_PERMISSIONS.get(role, set())   # unknown role: empty set, so deny

for role, action in (("learner", "take_quiz"), ("learner", "edit_course"), ("admin", "edit_course"), ("visitor", "read_lesson")):
    print(f"{role:8} {action:14} {'ALLOW' if allowed(role, action) else 'DENY'}")

import sqlite3

db = sqlite3.connect(":memory:")
db.execute("CREATE TABLE users (name TEXT, secret TEXT)")
db.executemany("INSERT INTO users VALUES (?, ?)", [("alice", "a-secret"), ("bob", "b-secret")])

def lookup_unsafe(name):
    return db.execute(f"SELECT name FROM users WHERE name = '{name}'").fetchall()

def lookup_safe(name):
    return db.execute("SELECT name FROM users WHERE name = ?", (name,)).fetchall()

attack = "x' OR '1'='1"
print("unsafe:", lookup_unsafe(attack))
print("safe:  ", lookup_safe(attack))

import ipaddress

RULES = [   # (action, protocol, port, source network). First match wins; the last rule is the default.
    ("allow", "tcp", 443, "0.0.0.0/0"),       # HTTPS from anywhere
    ("allow", "tcp", 22, "10.0.0.0/8"),       # SSH only from the internal network
    ("deny", "any", None, "0.0.0.0/0"),       # everything else
]

def decide(protocol, port, source):
    for action, rule_proto, rule_port, network in RULES:
        if rule_proto in (protocol, "any") and rule_port in (port, None) and ipaddress.ip_address(source) in ipaddress.ip_network(network):
            return action

for packet in (("tcp", 443, "203.0.113.9"), ("tcp", 22, "203.0.113.9"), ("tcp", 22, "10.1.2.3"), ("udp", 53, "10.1.2.3")):
    print(packet, "->", decide(*packet))

def parse(version):
    return tuple(int(part) for part in version.split("."))

MINIMUM_PATCHED = {"openssl": "3.0.13", "nginx": "1.25.4"}        # illustrative thresholds, not real advisories
inventory = {"openssl": "3.0.2", "nginx": "1.26.1", "curl": "8.5.0"}

for name, installed in inventory.items():
    if name not in MINIMUM_PATCHED:
        status = "UNKNOWN (no baseline)"
    elif parse(installed) < parse(MINIMUM_PATCHED[name]):
        status = "NEEDS PATCH"
    else:
        status = "ok"
    print(f"{name:8} {installed:8} {status}")

def naive_in_scope(host, scope):
    return host.endswith(scope)                       # wrong: matches look-alike domains

def in_scope(host, scope):
    return host == scope or host.endswith("." + scope)    # exact domain or a real subdomain

scope = "example.com"
for host in ("example.com", "api.example.com", "notexample.com", "example.com.evil.test"):
    print(f"{host:24} naive={naive_in_scope(host, scope)!s:5} correct={in_scope(host, scope)}")
